"""Run against Start-BackgroundEditor.ps1 with the Connect.osmap fixture generated by this suite."""
import json, math, pathlib, socket, sys
run = pathlib.Path(sys.argv[1]).resolve()
meta = json.loads(next((run / 'live').glob('editor-*.json')).read_text())
sock = socket.create_connection(('127.0.0.1', meta['port']), timeout=90)
stream = sock.makefile('rwb')
stream.write((json.dumps(dict(auth=meta['token'], client='connector-ui-check')) + '\n').encode()); stream.flush()
assert json.loads(stream.readline())['ok']
seq = 0
def call(method, params=None):
    global seq
    seq += 1
    stream.write((json.dumps(dict(id=seq, method=method, params=params or {})) + '\n').encode()); stream.flush()
    reply = json.loads(stream.readline()); assert 'error' not in reply, reply
    return reply['result']
def step(op, **args): return call('ui.input', dict(steps=[dict(op=op, frames=6, **args)]))
def tree(): return call('ui.tree', dict(limit=1200))
def guide_open(): return any(c.get('currentTab') == 'Your first map' for c in tree()['controls'])
def open_guide():
    step('click', at='menu:Help'); step('click', at='item:Your First Map'); assert guide_open()
def shot(name): call('ui.shot', dict(name=name, dir=str(run)))
def project(point):
    camera = call('editor')['camera']; p, y, _ = [v * math.tau / 65536 for v in camera['rot']]
    forward = (math.cos(p)*math.cos(y), math.cos(p)*math.sin(y), math.sin(p))
    right = (-math.sin(y), math.cos(y), 0); up = (-math.sin(p)*math.cos(y), -math.sin(p)*math.sin(y), math.cos(p))
    rel = [a-b for a,b in zip(point,camera['loc'])]; dot = lambda a,b: sum(x*y for x,y in zip(a,b))
    x,y,w,h = next(c['rect'] for c in tree()['controls'] if c['path'].endswith('/Perspective'))
    depth = dot(rel,forward)
    return [x+w/2+dot(rel,right)*w/(2*depth), y+h/2-dot(rel,up)*w/(2*depth)]

tree(); assert call('editor')['map'] == 'Connections', 'Use the disposable Connections fixture'
assert not guide_open(), 'Tutorial must start closed'
for action in ('tools.stairs','tools.windows'):
    button = next(c for c in tree()['controls'] if c.get('action') == action)
    assert not button.get('text'), 'Palette buttons must be icon-only'
    step('click', at='action:'+action)
    assert any(c.get('currentTab') == ('Stairs' if action.endswith('stairs') else 'Windows') for c in tree()['controls'])
step('escape')
for scale in (100,150):
    step('click',at='menu:View'); step('hover',at='item:UI Scale'); step('click',at=f'item:{scale}%'); step('escape')
    open_guide(); shot(f'tutorial-{scale}')
    step('click',at='tab:Your first map',button='middle'); assert not guide_open()
    open_guide(); step('click',at='tab:Inspector')
    step('rightClick',at='tab:Your first map'); step('click',at='item:Close'); assert not guide_open()
    open_guide(); folder=call('editor')['folder']; call('save'); call('open',dict(path=folder))
    assert not guide_open(), 'Even a saved open tutorial must start closed when opening a map'
print('PASS icon buttons; tutorial middle/right close, inactive tab and reload at 100%/150%')
step('click',at='menu:View'); step('hover',at='item:UI Scale'); step('click',at='item:100%'); step('escape')
step('click',at='action:tools.face'); step('key',key='Alt+6')
for sign in (-1,1):
    point=[-180,0,0 if sign<0 else 384]
    call('apply',dict(ops=[dict(op='workspace',camera=dict(at=[-400,-400,200],rot=[-5000 if sign<0 else 5000,8192,0]))]))
    xy=project(point); step('hover',at=xy)
    step('click',at=xy); assert not tree()['popups'], 'Ordinary surface click must select, not open connectors'
    step('hover',at=xy)
    badge=project([point[0],point[1],point[2]-sign*2]); badge=[badge[0]+18,badge[1]-18]
    step('hover',at=badge); step('click',at=badge)
    menus=tree()['popups']; items=[i['text'] for m in menus for i in m.get('items',[]) if 'text' in i]
    assert 'Add Hatch Opening' in items and ('Add Shaft Up' if sign>0 else 'Add Shaft Down') in items,items
    assert ('Add Room Above' if sign>0 else 'Add Room Below') in items and 'Connect Stairs…' in items,items
    shot('ceiling-connectors' if sign>0 else 'floor-connectors')
    before=call('summary')['counts']['brushes']
    step('click',at='item:Add Hatch Opening'); assert call('summary')['counts']['brushes']==before+1
    call('undo'); assert call('summary')['counts']['brushes']==before
    call('redo'); assert call('summary')['counts']['brushes']==before+1
    call('undo')
    print('PASS floor/ceiling connector menu, stable badge, hatch placement and undo/redo',sign)
shot('connectors-ready')
